package neueda.in.TransactionMonitoring.controller;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import neueda.in.TransactionMonitoring.DTO.ResponseDTO.TransactionEvaluationResponseDTO;
import neueda.in.TransactionMonitoring.service.RuleEngineService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * Person 3 — Rule Engine Controller.
 * Exposes a single debug/testing endpoint for manually triggering rule evaluation.
 * In production, evaluation is driven automatically via TransactionRecordedEvent.
 */
@RestController
@RequestMapping("/api/v1/rules")
@RequiredArgsConstructor
@Slf4j
public class RuleEngineController {

    private final RuleEngineService ruleEngineService;

    /**
     * POST /api/v1/rules/evaluate/{transactionId}
     *
     * Manually triggers rule evaluation for a transaction.
     * Useful for debugging, re-evaluation, and integration testing.
     *
     * @param transactionId the ID of the transaction to evaluate
     * @return evaluation report with all rule results and any created alerts
     */
    @PostMapping("/evaluate/{transactionId}")
    public ResponseEntity<TransactionEvaluationResponseDTO> evaluateTransaction(
            @PathVariable Long transactionId) {
        log.info("Manual evaluation triggered for transactionId={}", transactionId);
        TransactionEvaluationResponseDTO response = ruleEngineService.evaluateTransaction(transactionId);
        return ResponseEntity.ok(response);
    }
}

package neueda.in.TransactionMonitoring.converter;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.persistence.AttributeConverter;
import jakarta.persistence.Converter;

import java.util.Map;

/**
 * JPA converter to serialize/deserialize alert_details JSON column.
 */
@Converter
public class JsonConverter implements AttributeConverter<Map<String, Object>, String> {

    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();

    @Override
    public String convertToDatabaseColumn(Map<String, Object> attribute) {
        if (attribute == null || attribute.isEmpty()) {
            return null;
        }
        try {
            return OBJECT_MAPPER.writeValueAsString(attribute);
        } catch (JsonProcessingException e) {
            throw new IllegalArgumentException("Error serializing alert_details to JSON", e);
        }
    }

    @Override
    public Map<String, Object> convertToEntityAttribute(String dbData) {
        if (dbData == null || dbData.isBlank()) {
            return null;
        }
        try {
            return OBJECT_MAPPER.readValue(dbData, new TypeReference<Map<String, Object>>() {});
        } catch (JsonProcessingException e) {
            throw new IllegalArgumentException("Error deserializing alert_details from JSON", e);
        }
    }
}

package neueda.in.TransactionMonitoring.converter;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.persistence.AttributeConverter;
import jakarta.persistence.Converter;

import java.util.LinkedHashMap;
import java.util.Map;

@Converter
public class JsonMapConverter implements AttributeConverter<Map<String, Object>, String> {

    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();

    @Override
    public String convertToDatabaseColumn(Map<String, Object> attribute) {
        if (attribute == null || attribute.isEmpty()) {
            return "{}";
        }
        try {
            return OBJECT_MAPPER.writeValueAsString(attribute);
        } catch (JsonProcessingException e) {
            throw new IllegalArgumentException("Error serializing map to JSON", e);
        }
    }

    @Override
    public Map<String, Object> convertToEntityAttribute(String dbData) {
        if (dbData == null || dbData.isBlank()) {
            return new LinkedHashMap<>();
        }
        try {
            return OBJECT_MAPPER.readValue(dbData, new TypeReference<Map<String, Object>>() { });
        } catch (JsonProcessingException e) {
            throw new IllegalArgumentException("Error deserializing JSON to map", e);
        }
    }
}

package neueda.in.TransactionMonitoring.entity;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Account entity — owned by Person 1.
 * Person 3 reads this as a reference for alert account linkage.
 */
@Entity
@Table(name = "accounts")
@Data
@NoArgsConstructor
@AllArgsConstructor
public class Account {

    @Id
    @Column(name = "account_id", length = 50, nullable = false)
    private String accountId;

    @Column(name = "account_holder_name", length = 100)
    private String accountHolderName;

    @Column(name = "account_type", length = 50)
    private String accountType;

    @Column(name = "is_active")
    private Boolean isActive = true;
}

package neueda.in.TransactionMonitoring.entity;

import jakarta.persistence.*;
import lombok.*;
import neueda.in.TransactionMonitoring.converter.JsonConverter;
import neueda.in.TransactionMonitoring.enums.AlertStatus;
import neueda.in.TransactionMonitoring.enums.Severity;

import java.time.LocalDateTime;
import java.util.Map;

/**
 * Alert entity — created and owned by Person 3.
 * Maps 1:1 to the alerts table.
 */
@Entity
@Table(
    name = "alerts",
    indexes = {
        @Index(name = "idx_status",         columnList = "alert_status"),
        @Index(name = "idx_account_id",     columnList = "account_id"),
        @Index(name = "idx_created_at",     columnList = "created_at"),
        @Index(name = "idx_rule_id",        columnList = "rule_id"),
        @Index(name = "idx_status_created", columnList = "alert_status, created_at")
    }
)
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class Alert {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "alert_id")
    private Long alertId;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "rule_id", nullable = false)
    private Rule rule;

    @Column(name = "account_id", length = 50, nullable = false)
    private String accountId;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "transaction_id", nullable = false)
    private Transaction transaction;

    @Builder.Default
    @Enumerated(EnumType.STRING)
    @Column(name = "alert_status", length = 20, nullable = false)
    private AlertStatus alertStatus = AlertStatus.OPEN;

    @Enumerated(EnumType.STRING)
    @Column(name = "severity", length = 20, nullable = false)
    private Severity severity;

    @Column(name = "alert_message", columnDefinition = "TEXT", nullable = false)
    private String alertMessage;

    @Convert(converter = JsonConverter.class)
    @Column(name = "alert_details", columnDefinition = "JSON")
    private Map<String, Object> alertDetails;

    @Column(name = "created_at", nullable = false, updatable = false)
    private LocalDateTime createdAt;

    @Column(name = "acknowledged_at")
    private LocalDateTime acknowledgedAt;

    @Column(name = "investigating_at")
    private LocalDateTime investigatingAt;

    @Column(name = "closed_at")
    private LocalDateTime closedAt;

    @Column(name = "closed_reason", columnDefinition = "TEXT")
    private String closedReason;

    @Column(name = "closed_by", length = 50)
    private String closedBy;

    @Column(name = "updated_at", nullable = false)
    private LocalDateTime updatedAt;

    @PrePersist
    protected void onCreate() {
        createdAt = LocalDateTime.now();
        updatedAt = LocalDateTime.now();
        if (alertStatus == null) {
            alertStatus = AlertStatus.OPEN;
        }
    }

    @PreUpdate
    protected void onUpdate() {
        updatedAt = LocalDateTime.now();
    }
}

package neueda.in.TransactionMonitoring.entity;

import jakarta.persistence.Column;
import jakarta.persistence.Convert;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Index;
import jakarta.persistence.PrePersist;
import jakarta.persistence.PreUpdate;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;
import neueda.in.TransactionMonitoring.converter.JsonMapConverter;
import neueda.in.TransactionMonitoring.enums.RuleSeverity;
import neueda.in.TransactionMonitoring.enums.RuleStatus;
import neueda.in.TransactionMonitoring.enums.RuleType;

import java.time.OffsetDateTime;
import java.util.LinkedHashMap;
import java.util.Map;

@Entity
@Table(name = "rules", indexes = {
       @Index(name = "idx_rules_status", columnList = "status"),
       @Index(name = "idx_rules_type", columnList = "rule_type"),
       @Index(name = "idx_rules_name", columnList = "name")
})
@Getter
@Setter
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class Rule {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false, length = 120, unique = true)
    private String name;

    @Column(length = 500)
    private String description;

    @Enumerated(EnumType.STRING)
    @Column(name = "rule_type", nullable = false, length = 50)
    private RuleType ruleType;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private RuleStatus status;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private RuleSeverity severity;

    @Convert(converter = JsonMapConverter.class)
    @Column(name = "parameters_json", nullable = false, columnDefinition = "TEXT")
    @Builder.Default
    private Map<String, Object> parameters = new LinkedHashMap<>();

    @Column(name = "created_by", nullable = false, length = 100)
    private String createdBy;

    @Column(name = "updated_by", nullable = false, length = 100)
    private String updatedBy;

    @Column(name = "created_at", nullable = false)
    private OffsetDateTime createdAt;

    @Column(name = "updated_at", nullable = false)
    private OffsetDateTime updatedAt;

    @Version
    private Long version;

    @PrePersist
    void onCreate() {
       OffsetDateTime now = OffsetDateTime.now();
       createdAt = now;
       updatedAt = now;
       if (status == null) {
          status = RuleStatus.INACTIVE;
       }
    }

    @PreUpdate
    void onUpdate() {
       updatedAt = OffsetDateTime.now();
    }
}

