package neueda.in.TransactionMonitoring.rule;

import neueda.in.TransactionMonitoring.DTO.ResponseDTO.RuleEvaluationResultDTO;
import neueda.in.TransactionMonitoring.entity.Rule;
import neueda.in.TransactionMonitoring.entity.Transaction;
import neueda.in.TransactionMonitoring.enums.RuleType;
import neueda.in.TransactionMonitoring.enums.Severity;
import org.springframework.stereotype.Component;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

/**
 * Triggers when a single transaction amount exceeds the configured threshold.
 */
@Component
public class AmountThresholdEvaluator implements RuleEvaluator {

    @Override
    public boolean supports(RuleType ruleType) {
        return RuleType.AMOUNT_THRESHOLD.equals(ruleType);
    }

    @Override
    public RuleEvaluationResultDTO evaluate(Transaction transaction, Rule rule) {
        BigDecimal thresholdAmount = extractBigDecimal(rule.getParameters(), "thresholdAmount", "threshold_amount");
        boolean matched = transaction.getAmount() != null
                && thresholdAmount != null
                && transaction.getAmount().compareTo(thresholdAmount) > 0;

        Map<String, Object> details = new HashMap<>();
        details.put("transactionAmount", transaction.getAmount());
        details.put("thresholdAmount", thresholdAmount);
        details.put("accountId", transaction.getAccountId());

        return RuleEvaluationResultDTO.builder()
                .ruleId(rule.getId())
                .ruleName(rule.getName())
                .ruleType(rule.getRuleType())
                .matched(matched)
                .matchReason(matched
                        ? String.format("Transaction amount %.2f exceeds threshold %.2f for rule '%s'",
                                transaction.getAmount(), thresholdAmount, rule.getName())
                        : String.format("Amount %.2f is within threshold %.2f",
                                transaction.getAmount(), thresholdAmount))
                .severity(Severity.valueOf(rule.getSeverity().name()))
                .matchDetails(details)
                .build();
    }

    private BigDecimal extractBigDecimal(Map<String, Object> parameters, String... keys) {
        if (parameters == null) {
            return null;
        }
        for (String key : keys) {
            Object value = parameters.get(key);
            if (value != null) {
                try {
                    return new BigDecimal(String.valueOf(value));
                } catch (NumberFormatException ignored) {
                    return null;
                }
            }
        }
        return null;
    }
}

package neueda.in.TransactionMonitoring.rule;

import lombok.RequiredArgsConstructor;
import neueda.in.TransactionMonitoring.DTO.ResponseDTO.RuleEvaluationResultDTO;
import neueda.in.TransactionMonitoring.entity.Rule;
import neueda.in.TransactionMonitoring.entity.Transaction;
import neueda.in.TransactionMonitoring.enums.RuleType;
import neueda.in.TransactionMonitoring.enums.Severity;
import neueda.in.TransactionMonitoring.repository.TransactionRepository;
import org.springframework.stereotype.Component;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/**
 * Triggers when the cumulative transaction total for an account exceeds the configured daily limit.
 */
@Component
@RequiredArgsConstructor
public class DailyLimitEvaluator implements RuleEvaluator {

    private final TransactionRepository transactionRepository;

    @Override
    public boolean supports(RuleType ruleType) {
        return RuleType.DAILY_LIMIT.equals(ruleType);
    }

    @Override
    public RuleEvaluationResultDTO evaluate(Transaction transaction, Rule rule) {
        BigDecimal dailyLimitAmount = extractBigDecimal(rule.getParameters(), "dailyLimitAmount", "daily_limit_amount");
        LocalDateTime startOfDay = transaction.getTransactionDate().toLocalDate().atStartOfDay();
        LocalDateTime endOfDay   = startOfDay.plusDays(1);

        List<Transaction> dailyTransactions = transactionRepository
                .findByAccountIdAndTransactionDateBetween(transaction.getAccountId(), startOfDay, endOfDay);

        BigDecimal dailyTotal = dailyTransactions.stream()
                .map(Transaction::getAmount)
                .filter(Objects::nonNull)
                .reduce(BigDecimal.ZERO, BigDecimal::add);

        boolean matched = dailyLimitAmount != null
                && dailyTotal.compareTo(dailyLimitAmount) > 0;

        Map<String, Object> details = new HashMap<>();
        details.put("dailyTotal", dailyTotal);
        details.put("dailyLimit", dailyLimitAmount);
        details.put("transactionsToday", dailyTransactions.size());
        details.put("accountId", transaction.getAccountId());
        details.put("date", startOfDay.toLocalDate().toString());

        return RuleEvaluationResultDTO.builder()
                .ruleId(rule.getId())
                .ruleName(rule.getName())
                .ruleType(rule.getRuleType())
                .matched(matched)
                .matchReason(matched
                        ? String.format("Daily cumulative total %.2f exceeds limit %.2f for account %s on %s",
                                dailyTotal, dailyLimitAmount,
                                transaction.getAccountId(),
                                startOfDay.toLocalDate())
                        : String.format("Daily total %.2f is within limit %.2f",
                                dailyTotal, dailyLimitAmount))
                .severity(Severity.valueOf(rule.getSeverity().name()))
                .matchDetails(details)
                .build();
    }

    private BigDecimal extractBigDecimal(Map<String, Object> parameters, String... keys) {
        if (parameters == null) {
            return null;
        }
        for (String key : keys) {
            Object value = parameters.get(key);
            if (value != null) {
                try {
                    return new BigDecimal(String.valueOf(value));
                } catch (NumberFormatException ignored) {
                    return null;
                }
            }
        }
        return null;
    }
}

package neueda.in.TransactionMonitoring.rule;

import lombok.RequiredArgsConstructor;
import neueda.in.TransactionMonitoring.DTO.ResponseDTO.RuleEvaluationResultDTO;
import neueda.in.TransactionMonitoring.entity.Rule;
import neueda.in.TransactionMonitoring.entity.Transaction;
import neueda.in.TransactionMonitoring.enums.RuleType;
import neueda.in.TransactionMonitoring.enums.Severity;
import neueda.in.TransactionMonitoring.repository.TransactionRepository;
import org.springframework.stereotype.Component;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Triggers when money is sent to a payee that this account has never transacted with before.
 */
@Component
@RequiredArgsConstructor
public class NewPayeeEvaluator implements RuleEvaluator {

    private final TransactionRepository transactionRepository;

    @Override
    public boolean supports(RuleType ruleType) {
        return RuleType.NEW_PAYEE.equals(ruleType);
    }

    @Override
    public RuleEvaluationResultDTO evaluate(Transaction transaction, Rule rule) {
        Map<String, Object> details = new HashMap<>();

        if (transaction.getPayeeAccountId() == null || transaction.getPayeeAccountId().isBlank()) {
            details.put("reason", "No payee account on transaction");
            return RuleEvaluationResultDTO.builder()
                    .ruleId(rule.getId())
                    .ruleName(rule.getName())
                    .ruleType(rule.getRuleType())
                    .matched(false)
                    .matchReason("No payee account specified on transaction")
                    .severity(Severity.valueOf(rule.getSeverity().name()))
                    .matchDetails(details)
                    .build();
        }

        List<Transaction> allTransactionsToPayee = transactionRepository
                .findByAccountIdAndPayeeAccountId(transaction.getAccountId(), transaction.getPayeeAccountId());

        // Exclude the current transaction — anything before it is a "prior" transaction
        long priorCount = allTransactionsToPayee.stream()
                .filter(t -> t.getTransactionDate().isBefore(transaction.getTransactionDate()))
                .count();

        boolean isNewPayee = priorCount == 0;

        details.put("payeeAccountId", transaction.getPayeeAccountId());
        details.put("priorTransactionsToPayee", priorCount);
        details.put("accountId", transaction.getAccountId());

        return RuleEvaluationResultDTO.builder()
                .ruleId(rule.getId())
                .ruleName(rule.getName())
                .ruleType(rule.getRuleType())
                .matched(isNewPayee)
                .matchReason(isNewPayee
                        ? String.format("First-ever transaction from account %s to new payee %s",
                                transaction.getAccountId(), transaction.getPayeeAccountId())
                        : String.format("Payee %s is known (%d prior transactions)",
                                transaction.getPayeeAccountId(), priorCount))
                .severity(Severity.valueOf(rule.getSeverity().name()))
                .matchDetails(details)
                .build();
    }
}

package neueda.in.TransactionMonitoring.rule;

import neueda.in.TransactionMonitoring.DTO.ResponseDTO.RuleEvaluationResultDTO;
import neueda.in.TransactionMonitoring.entity.Rule;
import neueda.in.TransactionMonitoring.entity.Transaction;
import neueda.in.TransactionMonitoring.enums.RuleType;

/**
 * Strategy interface for rule evaluation.
 * Each implementation handles one RuleType.
 */
public interface RuleEvaluator {

    /** Returns true if this evaluator handles the given rule type */
    boolean supports(RuleType ruleType);

    /**
     * Evaluates the transaction against the rule.
     *
     * @param transaction the transaction being checked
     * @param rule        the rule definition with thresholds/parameters
     * @return evaluation result with match flag, reason text, and context details
     */
    RuleEvaluationResultDTO evaluate(Transaction transaction, Rule rule);
}

package neueda.in.TransactionMonitoring.rule;

import lombok.RequiredArgsConstructor;
import neueda.in.TransactionMonitoring.enums.RuleType;
import org.springframework.stereotype.Component;

import java.util.List;

/**
 * Resolves the correct RuleEvaluator for a given RuleType.
 * Spring auto-injects all RuleEvaluator beans via the list.
 */
@Component
@RequiredArgsConstructor
public class RuleEvaluatorFactory {

    private final List<RuleEvaluator> evaluators;

    /**
     * Returns the evaluator that supports the given rule type.
     *
     * @throws IllegalArgumentException if no evaluator is registered for the type
     */
    public RuleEvaluator getEvaluator(RuleType ruleType) {
        return evaluators.stream()
                .filter(e -> e.supports(ruleType))
                .findFirst()
                .orElseThrow(() -> new IllegalArgumentException(
                        "No RuleEvaluator registered for rule type: " + ruleType));
    }
}

package neueda.in.TransactionMonitoring.rule;

import lombok.RequiredArgsConstructor;
import neueda.in.TransactionMonitoring.DTO.ResponseDTO.RuleEvaluationResultDTO;
import neueda.in.TransactionMonitoring.entity.Rule;
import neueda.in.TransactionMonitoring.entity.Transaction;
import neueda.in.TransactionMonitoring.enums.RuleType;
import neueda.in.TransactionMonitoring.enums.Severity;
import neueda.in.TransactionMonitoring.repository.TransactionRepository;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;
import java.util.HashMap;
import java.util.Map;

/**
 * Triggers when an account has too many transactions within a rolling time window.
 * Example: more than 5 transactions in 60 minutes.
 */
@Component
@RequiredArgsConstructor
public class VelocityEvaluator implements RuleEvaluator {

    private final TransactionRepository transactionRepository;

    @Override
    public boolean supports(RuleType ruleType) {
        return RuleType.VELOCITY.equals(ruleType);
    }

    @Override
    public RuleEvaluationResultDTO evaluate(Transaction transaction, Rule rule) {
        int windowMinutes = extractInteger(rule.getParameters(), 60, "velocityWindowMinutes", "velocity_window_minutes");
        int maxCount = extractInteger(rule.getParameters(), 5, "velocityCount", "velocity_count");

        LocalDateTime windowStart = transaction.getTransactionDate().minusMinutes(windowMinutes);
        long count = transactionRepository.countByAccountIdAndTransactionDateBetween(
                transaction.getAccountId(), windowStart, transaction.getTransactionDate());

        // The current transaction is included in count, so threshold is maxCount+1
        boolean matched = count > maxCount;

        Map<String, Object> details = new HashMap<>();
        details.put("transactionCountInWindow", count);
        details.put("maxAllowed", maxCount);
        details.put("windowMinutes", windowMinutes);
        details.put("windowStart", windowStart.toString());
        details.put("accountId", transaction.getAccountId());

        return RuleEvaluationResultDTO.builder()
                .ruleId(rule.getId())
                .ruleName(rule.getName())
                .ruleType(rule.getRuleType())
                .matched(matched)
                .matchReason(matched
                        ? String.format("High velocity: %d transactions in last %d minutes (max allowed: %d) for account %s",
                                count, windowMinutes, maxCount, transaction.getAccountId())
                        : "Transaction velocity within acceptable limits")
                .severity(Severity.valueOf(rule.getSeverity().name()))
                .matchDetails(details)
                .build();
    }

    private int extractInteger(Map<String, Object> parameters, int defaultValue, String... keys) {
        if (parameters == null) {
            return defaultValue;
        }
        for (String key : keys) {
            Object value = parameters.get(key);
            if (value != null) {
                try {
                    return Integer.parseInt(String.valueOf(value));
                } catch (NumberFormatException ignored) {
                    return defaultValue;
                }
            }
        }
        return defaultValue;
    }
}

package neueda.in.TransactionMonitoring.service;

import jakarta.persistence.EntityNotFoundException;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import neueda.in.TransactionMonitoring.DTO.RequestDTO.AlertCreationRequestDTO;
import neueda.in.TransactionMonitoring.DTO.ResponseDTO.AlertResponseDTO;
import neueda.in.TransactionMonitoring.entity.Alert;
import neueda.in.TransactionMonitoring.entity.Rule;
import neueda.in.TransactionMonitoring.entity.Transaction;
import neueda.in.TransactionMonitoring.enums.AlertStatus;
import neueda.in.TransactionMonitoring.event.AlertCreatedEvent;
import neueda.in.TransactionMonitoring.repository.AlertRepository;
import neueda.in.TransactionMonitoring.repository.RuleRepository;
import neueda.in.TransactionMonitoring.repository.TransactionRepository;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Person 3 — Alert Service.
 * Responsible for persisting new alert records and publishing AlertCreatedEvent.
 * Does NOT handle lifecycle actions (acknowledge / close / dismiss) — those belong to Person 4.
 */
@Service
@RequiredArgsConstructor
@Slf4j
public class AlertService {

    private final AlertRepository alertRepository;
    private final TransactionRepository transactionRepository;
    private final RuleRepository ruleRepository;
    private final ApplicationEventPublisher eventPublisher;

    /**
     * Creates a new alert record from the given request payload.
     * Returns null (and logs a warning) if a duplicate alert already exists
     * for the same rule + transaction combination.
     */
    @Transactional
    public AlertResponseDTO createAlert(AlertCreationRequestDTO request) {

        // ── Duplicate prevention ──────────────────────────────────────────────
        if (alertRepository.existsByRule_IdAndTransaction_TransactionId(
                request.getRuleId(), request.getTransactionId())) {
            log.warn("Duplicate alert skipped — ruleId={} transactionId={}",
                    request.getRuleId(), request.getTransactionId());
            return null;
        }

        // ── Resolve FK entities ───────────────────────────────────────────────
        Rule rule = ruleRepository.findById(request.getRuleId())
                .orElseThrow(() -> new EntityNotFoundException(
                        "Rule not found with id: " + request.getRuleId()));

        Transaction transaction = transactionRepository.findById(request.getTransactionId())
                .orElseThrow(() -> new EntityNotFoundException(
                        "Transaction not found with id: " + request.getTransactionId()));

        // ── Build and persist ─────────────────────────────────────────────────
        Alert alert = Alert.builder()
                .rule(rule)
                .accountId(request.getAccountId())
                .transaction(transaction)
                .alertStatus(AlertStatus.OPEN)
                .severity(request.getSeverity())
                .alertMessage(request.getAlertMessage())
                .alertDetails(request.getAlertDetails())
                .build();

        Alert saved = alertRepository.save(alert);
        log.info("Alert created — alertId={} ruleId={} transactionId={} severity={}",
                saved.getAlertId(), rule.getId(), transaction.getTransactionId(), saved.getSeverity());

        // ── Publish event for Person 4 ────────────────────────────────────────
        AlertResponseDTO response = toResponseDTO(saved);
        eventPublisher.publishEvent(new AlertCreatedEvent(this, response));
        return response;
    }

    // ── Mapper ────────────────────────────────────────────────────────────────

    private AlertResponseDTO toResponseDTO(Alert alert) {
        return AlertResponseDTO.builder()
                .alertId(alert.getAlertId())
                .ruleId(alert.getRule().getId())
                .ruleName(alert.getRule().getName())
                .accountId(alert.getAccountId())
                .transactionId(alert.getTransaction().getTransactionId())
                .alertStatus(alert.getAlertStatus())
                .severity(alert.getSeverity())
                .alertMessage(alert.getAlertMessage())
                .alertDetails(alert.getAlertDetails())
                .createdAt(alert.getCreatedAt())
                .updatedAt(alert.getUpdatedAt())
                .build();
    }
}

package neueda.in.TransactionMonitoring.service;

import jakarta.persistence.EntityNotFoundException;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import neueda.in.TransactionMonitoring.DTO.RequestDTO.AlertCreationRequestDTO;
import neueda.in.TransactionMonitoring.DTO.ResponseDTO.AlertResponseDTO;
import neueda.in.TransactionMonitoring.DTO.ResponseDTO.RuleEvaluationResultDTO;
import neueda.in.TransactionMonitoring.DTO.ResponseDTO.TransactionEvaluationResponseDTO;
import neueda.in.TransactionMonitoring.entity.Rule;
import neueda.in.TransactionMonitoring.entity.Transaction;
import neueda.in.TransactionMonitoring.event.TransactionRecordedEvent;
import neueda.in.TransactionMonitoring.enums.RuleStatus;
import neueda.in.TransactionMonitoring.repository.RuleRepository;
import neueda.in.TransactionMonitoring.repository.TransactionRepository;
import neueda.in.TransactionMonitoring.rule.RuleEvaluator;
import neueda.in.TransactionMonitoring.rule.RuleEvaluatorFactory;
import org.springframework.context.event.EventListener;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.ArrayList;
import java.util.List;

/**
 * Person 3 — Rule Engine Service.
 * Core responsibilities:
 *  1. Listen for TransactionRecordedEvent (auto-evaluation pipeline)
 *  2. Evaluate all active rules against the transaction
 *  3. Build AlertCreationRequestDTO payloads for every matching rule
 *  4. Delegate alert persistence to AlertService
 *  5. Return a full evaluation report (used by the debug endpoint and the event response)
 */
@Service
@RequiredArgsConstructor
@Slf4j
public class RuleEngineService {

    private final RuleRepository ruleRepository;
    private final TransactionRepository transactionRepository;
    private final AlertService alertService;
    private final RuleEvaluatorFactory evaluatorFactory;

    // ── Auto-evaluation via application event ─────────────────────────────────

    /**
     * Triggered automatically when Person 1 publishes a TransactionRecordedEvent.
     */
    @EventListener
    public void onTransactionRecorded(TransactionRecordedEvent event) {
        log.info("TransactionRecordedEvent received — transactionId={}", event.getTransactionId());
        evaluateTransaction(event.getTransactionId());
    }

    // ── Core evaluation logic ─────────────────────────────────────────────────

    /**
     * Evaluates all active rules against the given transaction.
     * Creates alerts for every matched rule (duplicates are suppressed by AlertService).
     *
     * @param transactionId the ID of the transaction to evaluate
     * @return full evaluation report
     */
    @Transactional
    public TransactionEvaluationResponseDTO evaluateTransaction(Long transactionId) {

        Transaction transaction = transactionRepository.findById(transactionId)
                .orElseThrow(() -> new EntityNotFoundException(
                        "Transaction not found with id: " + transactionId));

        List<Rule> activeRules = ruleRepository.findByStatus(RuleStatus.ACTIVE);
        log.debug("Evaluating transactionId={} against {} active rules", transactionId, activeRules.size());

        List<RuleEvaluationResultDTO> results       = new ArrayList<>();
        List<AlertResponseDTO>        createdAlerts = new ArrayList<>();

        for (Rule rule : activeRules) {
            try {
                RuleEvaluator evaluator = evaluatorFactory.getEvaluator(rule.getRuleType());
                RuleEvaluationResultDTO result = evaluator.evaluate(transaction, rule);
                results.add(result);

                if (result.isMatched()) {
                    AlertCreationRequestDTO alertRequest = buildAlertRequest(transaction, rule, result);
                    AlertResponseDTO alertResponse = alertService.createAlert(alertRequest);
                    if (alertResponse != null) {
                        createdAlerts.add(alertResponse);
                    }
                }

            } catch (IllegalArgumentException e) {
                log.warn("Skipping rule {} ({}): {}", rule.getId(), rule.getRuleType(), e.getMessage());
            } catch (Exception e) {
                log.error("Error evaluating rule {} for transaction {}: {}",
                        rule.getId(), transactionId, e.getMessage(), e);
            }
        }

        long matchedCount = results.stream().filter(RuleEvaluationResultDTO::isMatched).count();
        log.info("Evaluation complete — transactionId={} rules={} matched={} alertsCreated={}",
                transactionId, activeRules.size(), matchedCount, createdAlerts.size());

        return TransactionEvaluationResponseDTO.builder()
                .transactionId(transactionId)
                .rulesEvaluated(activeRules.size())
                .rulesMatched((int) matchedCount)
                .alertsCreated(createdAlerts.size())
                .evaluationResults(results)
                .createdAlerts(createdAlerts)
                .build();
    }

    // ── Helpers ───────────────────────────────────────────────────────────────

    private AlertCreationRequestDTO buildAlertRequest(Transaction transaction,
                                                       Rule rule,
                                                       RuleEvaluationResultDTO result) {
        return AlertCreationRequestDTO.builder()
                .ruleId(rule.getId())
                .accountId(transaction.getAccountId())
                .transactionId(transaction.getTransactionId())
                .severity(result.getSeverity())
                .alertMessage(result.getMatchReason())
                .alertDetails(result.getMatchDetails())
                .build();
    }
}

